#!/usr/bin/env python3
"""Render markdown snippet(s) with crowbook to HTML and extract chapter div."""
import os, sys, subprocess, re, shutil, tempfile

BIN = "/tmp/ref/crowbook"

def render(md, opts=None, chapters=None, extract=True, quiet=True, keep=False):
    d = tempfile.mkdtemp(prefix="cb", dir="/tmp/work/blk03")
    files = []
    if chapters is None:
        chapters = [("+", md)]
    for i, (kind, content) in enumerate(chapters):
        fn = "ch%d.md" % i
        with open(os.path.join(d, fn), "w") as f:
            f.write(content)
        files.append((kind, fn))
    conf = ["author: Au Thor", "title: My Book", "lang: en",
            "input.clean: false",
            "output.html: out.html"]
    if opts:
        conf.extend(opts)
    for kind, fn in files:
        conf.append("%s %s" % (kind, fn))
    with open(os.path.join(d, "book.conf"), "w") as f:
        f.write("\n".join(conf) + "\n")
    p = subprocess.run([BIN, "book.conf"], cwd=d, capture_output=True, text=True)
    out = os.path.join(d, "out.html")
    html = open(out).read() if os.path.exists(out) else None
    res = {"stdout": p.stdout, "stderr": p.stderr, "rc": p.returncode, "html": html, "dir": d}
    if html and extract:
        res["chaps"] = extract_chaps(html)
    if not keep:
        pass
    return res

def extract_chaps(html):
    # find all <div id = "chapter-N"> ... matching close
    out = []
    for m in re.finditer(r'<div id = "chapter-(\d+)">', html):
        start = m.start()
        # find matching close div by counting
        i = m.end()
        depth = 1
        while depth > 0:
            nxt = re.search(r'<div\b|</div>', html[i:])
            if not nxt:
                break
            if nxt.group(0) == '</div>':
                depth -= 1
            else:
                depth += 1
            i += nxt.end()
        out.append(html[start:i])
    return out

def show(md, opts=None, chapters=None, label=None, raw=False):
    r = render(md, opts, chapters)
    if label: print("=== %s ===" % label)
    if r["stderr"].strip(): print("[stderr] " + r["stderr"].strip())
    if r.get("chaps") is None:
        print("[NO HTML] rc=%s stdout=%s" % (r["rc"], r["stdout"]))
        return r
    for c in r["chaps"]:
        if raw:
            print(repr(c))
        else:
            print(c)
    return r

if __name__ == "__main__":
    md = sys.stdin.read()
    show(md)
PYEOF
